do $$
declare c jsonb := '[{"title": "Daily Cleaning", "title_mr": "रोजची साफसफाई", "included": [{"en": "Sweep and mop all reachable floors", "mr": "सर्व पोहोचण्याजोग्या फरशीवर झाडू-पोछा"}, {"en": "Dust and wipe furniture, shelves, doors and window sills", "mr": "फर्निचर, कपाटे, दारे व खिडकीच्या कडा पुसणे"}, {"en": "Dust reachable fans and remove cobwebs", "mr": "हाताला पोहोचणारे पंखे पुसणे व जाळी काढणे"}, {"en": "Bathroom: clean basin, taps, mirror and the toilet seat & bowl (regular clean)", "mr": "बाथरूम: बेसिन, नळ, आरसा व टॉयलेट सीट-भांडे (नेहमीची स्वच्छता)"}, {"en": "Mop and dry the bathroom floor", "mr": "बाथरूमची फरशी पुसून कोरडी करणे"}, {"en": "Collect wet and dry waste into the household dustbin", "mr": "ओला व सुका कचरा घरातील डस्टबिनमध्ये टाकणे"}], "not_included": [{"en": "Acid wash, hard stains or tile-grout cleaning", "mr": "ॲसिड वॉश, कडक डाग किंवा टाइल-ग्राउट साफसफाई"}, {"en": "Toilet deep cleaning (scaling, yellow stains)", "mr": "टॉयलेटची डीप क्लीनिंग (पिवळे डाग, थर)"}, {"en": "Work at height — ladders, ceilings, high fans, chandeliers", "mr": "उंचावरील काम — शिडी, छत, उंच पंखे, झुंबर"}, {"en": "Outside areas — exterior windows, grills, terrace, common stairs", "mr": "बाहेरील भाग — बाहेरच्या खिडक्या, ग्रिल, गच्ची, जिना"}, {"en": "Drain unclogging, plumbing or electrical work", "mr": "गटार मोकळे करणे, प्लंबिंग किंवा इलेक्ट्रिकल काम"}, {"en": "Moving heavy furniture or appliances", "mr": "जड फर्निचर किंवा उपकरणे हलवणे"}], "enabled": true}, {"title": "Kitchen Help", "title_mr": "स्वयंपाकघर मदत", "included": [{"en": "Wash everyday household utensils", "mr": "रोजची भांडी घासणे"}, {"en": "Clean kitchen slab, sink and stove top", "mr": "किचन ओटा, सिंक व गॅस शेगडी साफ करणे"}, {"en": "Wipe the outside of fridge, microwave and appliances", "mr": "फ्रिज, मायक्रोवेव्ह व उपकरणे बाहेरून पुसणे"}, {"en": "Basic prep: wash and chop vegetables", "mr": "भाज्या धुणे व चिरणे"}, {"en": "Arrange utensils and groceries back in place", "mr": "भांडी व किराणा जागेवर लावणे"}, {"en": "Throw kitchen waste and leave the sink area dry", "mr": "किचनचा कचरा टाकणे व सिंक कोरडे ठेवणे"}], "not_included": [{"en": "Cooking meals", "mr": "स्वयंपाक करणे"}, {"en": "Chimney, exhaust or duct cleaning", "mr": "चिमणी, एक्झॉस्ट किंवा डक्ट साफसफाई"}, {"en": "Deep cleaning inside fridge, oven or microwave", "mr": "फ्रिज, ओव्हन किंवा मायक्रोवेव्हची आतून डीप क्लीनिंग"}, {"en": "Heavy scrubbing of burnt or old deposits", "mr": "जळलेले किंवा जुने थर घासणे"}, {"en": "Handling broken glass or sharp waste", "mr": "फुटलेली काच किंवा धारदार कचरा हाताळणे"}, {"en": "Polishing silver, brass or special cookware", "mr": "चांदी, पितळ किंवा खास भांड्यांना पॉलिश"}], "enabled": true}, {"title": "Everyday Help", "title_mr": "घरातील इतर कामे", "included": [{"en": "Load the washing machine and dry clothes on line/rack", "mr": "वॉशिंग मशीन लावणे व कपडे वाळत घालणे"}, {"en": "Fold and arrange clothes in cupboards", "mr": "कपड्यांच्या घड्या करून कपाटात लावणे"}, {"en": "Change and arrange bedsheets and pillow covers", "mr": "बेडशीट व उशीचे अभ्रे बदलणे"}, {"en": "Arrange sofa cushions, tables and study area", "mr": "सोफा उशा, टेबल व अभ्यासाची जागा नीट लावणे"}, {"en": "Clean mirrors and glass inside the home", "mr": "घरातील आरसे व काच साफ करणे"}, {"en": "Tidy wardrobes and shelves", "mr": "कपाटे व शेल्फ नीट लावणे"}], "not_included": [{"en": "Ironing or steaming clothes", "mr": "कपड्यांना इस्त्री करणे"}, {"en": "Hand-washing blankets, carpets or footwear", "mr": "ब्लँकेट, कार्पेट किंवा चप्पल-बूट हाताने धुणे"}, {"en": "Stain removal or dry-clean items", "mr": "डाग काढणे किंवा ड्राय-क्लीनचे कपडे"}, {"en": "Child, elderly, pet or medical care", "mr": "लहान मुले, वृद्ध, पाळीव प्राणी किंवा रुग्णसेवा"}, {"en": "Cleaning the washing machine", "mr": "वॉशिंग मशीन साफ करणे"}, {"en": "Handling cash, jewellery or valuables", "mr": "पैसे, दागिने किंवा मौल्यवान वस्तू हाताळणे"}], "enabled": true}]'::jsonb; d jsonb := '{"included_title": "The expert is trained to", "included_title_mr": "मावशी हे काम करतील", "excluded_title": "Not included", "excluded_title_mr": "यात समाविष्ट नाही", "note": "Please keep cleaning supplies ready — broom, mop, bucket, cleaning liquid, cloth and detergent.", "note_mr": "कृपया साफसफाईचे साहित्य तयार ठेवा — झाडू, पोछा, बादली, क्लीनिंग लिक्विड, कापड व डिटर्जंट."}'::jsonb; p jsonb; before jsonb; i int;
begin
  select payload into before from homepage_sections where section_type='clean_content' and city_id is null;
  if before is null then
    p := (select r.content from service_content_resolve('clean', null) r);
  else p := before; end if;
  for i in 0..2 loop
    c := jsonb_set(c, array[i::text,'image_url'], coalesce(p->'cards'->i->'image_url','null'::jsonb));
    c := jsonb_set(c, array[i::text,'price_option_id'], coalesce(p->'cards'->i->'price_option_id','null'::jsonb));
    if p->'cards'->i ? 'enabled' then c := jsonb_set(c, array[i::text,'enabled'], p->'cards'->i->'enabled'); end if;
  end loop;
  p := jsonb_set(p, '{cards}', c);
  p := jsonb_set(p, '{details}', coalesce(p->'details','{}'::jsonb) || d);
  if before is null then
    insert into homepage_sections(section_type, display_order, is_active, payload, city_id, updated_at) values ('clean_content',0,true,p,null,now());
  else
    update homepage_sections set payload=p, updated_at=now() where section_type='clean_content' and city_id is null;
  end if;
  insert into audit_logs(actor_id, action, target_table, before_state, after_state) values ('00000000-0000-0000-0000-000000000000','save_clean_content','homepage_sections',before,p);
end $$;